/* isry.couns.mngr.consultantabltymng.mapper.DscsnAbilitMngMapper.selectEvlCnsttnList - 개발지원팀 이태호 */
SELECT T1.RLVT_YR AS RLVT_YR ,T1.EVL_TME_SE_CD AS EVL_CD ,T1.EVL_GROUP_SE_CD AS EVL_GROUP ,(SELECT CMMNS_CD_VALUE_NM FROM SAC100 x WHERE x.CMMNS_CD_ID = 'EVL_TME_SE_CD' AND x.CMMNS_CD_VALUE = T1.EVL_TME_SE_CD) AS EVL_TME_SE_CD --평가회차그룹코드 ,T1.RGTR_ID AS RGTR_ID ,T1.CRT_DT AS CRT_DT ,T1.CFMTN_YN AS CFMTN_YN ,(SELECT CMMNS_CD_VALUE_NM FROM SAC100 x WHERE x.CMMNS_CD_ID = 'EVL_GROUP_SE_CD' AND x.CMMNS_CD_VALUE = T1.EVL_GROUP_SE_CD) AS EVL_GROUP_SE_CD --평가그룹구분코드 ,T1.CHTT_WGHTVA_VALUE * 100 AS CHTT_WGHTVA_VALUE ,T1.NTABRD_WGHTVA_VALUE * 100 AS NTABRD_WGHTVA_VALUE ,T1.MSNGR_WGHTVA_VALUE * 100 AS MSNGR_WGHTVA_VALUE ,T1.PRFMNC_WGHTVA_VALUE * 100 AS PRFMNC_WGHTVA_VALUE ,CASE WHEN T1.CHTT_WGHTVA_VALUE IS NOT NULL THEN '채팅상담' WHEN T1.NTABRD_WGHTVA_VALUE IS NOT NULL THEN '게시판상담' WHEN T1.MSNGR_WGHTVA_VALUE IS NOT NULL THEN '메신저상담' WHEN T1.PRFMNC_WGHTVA_VALUE IS NOT NULL THEN '실적상담' END AS EVL_PRVSON ,CASE WHEN T1.CHTT_WGHTVA_VALUE IS NOT NULL THEN T1.CHTT_WGHTVA_VALUE || '%' WHEN T1.NTABRD_WGHTVA_VALUE IS NOT NULL THEN T1.NTABRD_WGHTVA_VALUE || '%' WHEN T1.MSNGR_WGHTVA_VALUE IS NOT NULL THEN T1.MSNGR_WGHTVA_VALUE || '%' WHEN T1.PRFMNC_WGHTVA_VALUE IS NOT NULL THEN T1.PRFMNC_WGHTVA_VALUE || '%' END AS RFLT_RATE ,T1.CHTT_BGNG_YMD AS CHTT_BGNG_YMD ,T1.CHTT_END_YMD AS CHTT_END_YMD ,T1.NTABRD_BGNG_YMD AS NTABRD_BGNG_YMD ,T1.NTABRD_END_YMD AS NTABRD_END_YMD ,T1.MSNGR_BGNG_YMD AS MSNGR_BGNG_YMD ,T1.MSNGR_END_YMD AS MSNGR_END_YMD ,T1.BGNG_YMD AS BGNG_YMD ,T1.END_YMD AS END_YMD ,T1.PRVSON_NM AS PRVSON_NM ,DECODE(T1.BGNG_YMD,NULL,'',SUBSTR(T1.BGNG_YMD,0,4) || '-' || SUBSTR(T1.BGNG_YMD,5,2) || '-' || SUBSTR(T1.BGNG_YMD,7,2) || '~' || SUBSTR(T1.END_YMD,0,4) || '-' || SUBSTR(T1.END_YMD,5,2) || '-' || SUBSTR(T1.END_YMD,7,2)) AS EVL_PRD ,T1.EVFO_MNG_SN AS EVFO_MNG_SN FROM AYC200 T1 /* 평가지관리 */ WHERE 1=1 AND T1.DEL_YN = 'N'
AND T1.RLVT_YR = #{RLVT_YR}
AND T1.EVL_GROUP_SE_CD = #{EVL_GROUP_SE_CD}
AND T1.EVL_TME_SE_CD = #{EVL_TME_SE_CD}

mapper.insert:

        /* isry.couns.mngr.consultantabltymng.mapper.DscsnAbilitMngMapper.InsertEvlCnsttn - 개발지원팀 이태호  */

            SELECT NVL(MAX(EVFO_MNG_SN)+1 ,1) FROM AYC200            

        INSERT INTO AYC200 /* 평가지관리 */
		    (EVFO_MNG_SN
		    , RLVT_YR
		    , EVL_TME_SE_CD
		    , RGTR_ID
		    , CRT_DT
		    , CFMTN_YN
		    , EVL_GROUP_SE_CD
		    , CHTT_WGHTVA_VALUE
		    , NTABRD_WGHTVA_VALUE
		    , MSNGR_WGHTVA_VALUE
		    , PRFMNC_WGHTVA_VALUE
		    , CHTT_BGNG_YMD
		    , CHTT_END_YMD
		    , NTABRD_BGNG_YMD
		    , NTABRD_END_YMD
		    , MSNGR_BGNG_YMD
		    , MSNGR_END_YMD
		    , BGNG_YMD
		    , END_YMD
		    , PRVSON_NM
		    , SRVY_KND_SE_CD1
		    , SRVY_KND_SE_CD2
		    , SRVY_KND_SE_CD3
		    , SRVY_KND_SE_CD4
		    , DEL_YN		    
		    , FRST_RGTR_ID
		    , FRST_REG_DT
		    , LAST_MDFR_ID
		    , LAST_MDFCN_DT
		    )
		VALUES
		    (#{MNG_SN}
		    , #{RLVT_YR}
		    , #{EVL_TME_SE_CD}
		    , #{RGTR_ID}
		    , SYSDATE
		    , NVL(#{CFMTN_YN},'N')
		    , #{EVL_GROUP_SE_CD}
		    , NVL(#{CHTT_WGHTVA_VALUE},0) / 100
		    , NVL(#{NTABRD_WGHTVA_VALUE},0) / 100
		    , NVL(#{MSNGR_WGHTVA_VALUE},0) / 100
		    , NVL(#{PRFMNC_WGHTVA_VALUE},0) / 100
		    , #{CHTT_BGNG_YMD}
		    , #{CHTT_END_YMD}
		    , #{NTABRD_BGNG_YMD}
		    , #{NTABRD_END_YMD}
		    , #{MSNGR_BGNG_YMD}
		    , #{MSNGR_END_YMD}
		    , #{BGNG_YMD}
		    , #{END_YMD}
		    , #{PRVSON_NM}
		    , #{SRVY_KND_SE_CD1}
		    , #{SRVY_KND_SE_CD2}
		    , #{SRVY_KND_SE_CD3}
		    , #{SRVY_KND_SE_CD4}
		    , NVL(#{DEL_YN},'N')
		    , #{FRST_RGTR_ID}
            , SYSDATE
            , #{LAST_MDFR_ID}
            , SYSDATE 
		    )


        /* isry.couns.mngr.consultantabltymng.mapper.DscsnAbilitMngMapper.InsertEvlCnsttnDtl - 개발지원팀 이태호  */        
        INSERT INTO AYC210 /* 평가자관리상세 */
            (EVFO_MNG_SN
			, APRAI_MNG_DTL_SN
			, APRAI_ID
			, APRAI_NM_ENCPT
			, CHTT_EVL_BGNG_YMD
			, CHTT_EVL_END_YMD
			, NTABRD_EVL_BGNG_YMD
			, NTABRD_EVL_END_YMD			
			, CRT_YMD
			, MSNGR_EVL_BGNG_YMD
			, MSNGR_EVL_END_YMD
			, DEL_YN
			, FRST_RGTR_ID
			, FRST_REG_DT
			, LAST_MDFR_ID
			, LAST_MDFCN_DT
			)
        VALUES
            (#{MNG_SN}
            , AYC210_SQ01.NEXTVAL
            , #{APRAI_ID}
            , #{APRAI_NM_ENCPT}
            , #{CHTT_EVL_BGNG_YMD}
            , #{CHTT_EVL_END_YMD}
            , #{NTABRD_EVL_BGNG_YMD}
            , #{NTABRD_EVL_END_YMD}            
            , #{CRT_YMD}            
            , #{MSNGR_EVL_BGNG_YMD}
            , #{MSNGR_EVL_END_YMD}
            , NVL(#{DEL_YN},'N')
            , #{FRST_RGTR_ID}
            , SYSDATE
            , #{LAST_MDFR_ID}
            , SYSDATE 
            )

mapper.select:

        /* isry.couns.mngr.consultantabltymng.mapper.DscsnAbilitMngMapper.selectEnfsnNm - 개발지원팀 이태호  */  
        SELECT FLNM_ENCPT AS FLNM_ENCPT
		  FROM SCA100 /* 종사자 */
		 WHERE 1=1
		   AND ENFSN_NO = #{ENFSN_NO}

