        /* isry.couns.mngr.consultantabltymng.mapper.DscsnAbilitMngMapper.UpdateEvlCnsttn - 개발지원팀 이태호  */
        UPDATE AYC200 /* 평가지관리 */
			SET RLVT_YR              = #{RLVT_YR}
			  , EVL_TME_SE_CD        = #{EVL_TME_SE_CD}
			  , EVL_GROUP_SE_CD      = #{EVL_GROUP_SE_CD}
			  , BGNG_YMD             = #{BGNG_YMD}
			  , END_YMD              = #{END_YMD}
			  , PRVSON_NM            = #{PRVSON_NM}
			  , CHTT_WGHTVA_VALUE    = NVL(#{CHTT_WGHTVA_VALUE},0) /100
			  , NTABRD_WGHTVA_VALUE  = NVL(#{NTABRD_WGHTVA_VALUE},0) /100
			  , MSNGR_WGHTVA_VALUE   = NVL(#{MSNGR_WGHTVA_VALUE},0) /100
			  , PRFMNC_WGHTVA_VALUE  = NVL(#{PRFMNC_WGHTVA_VALUE},0) /100
			  , SRVY_KND_SE_CD1     = #{SRVY_KND_SE_CD1}
			  , SRVY_KND_SE_CD2     = #{SRVY_KND_SE_CD2}
			  , SRVY_KND_SE_CD3     = #{SRVY_KND_SE_CD3}
			  , SRVY_KND_SE_CD4     = #{SRVY_KND_SE_CD4}
			  , LAST_MDFR_ID         = #{LAST_MDFR_ID}
			  , LAST_MDFCN_DT        = SYSDATE
	   WHERE EVFO_MNG_SN = #{EVFO_MNG_SN}


 /* isry.couns.mngr.consultantabltymng.mapper.DscsnAbilitMngMapper.UpdateCfmtnYn - 개발지원팀 이태호  */
 UPDATE AYC200 /* 평가지관리 */
     SET CFMTN_YN             = 'Y'              
       , LAST_MDFR_ID         = #{LAST_MDFR_ID}
       , LAST_MDFCN_DT        = SYSDATE
WHERE EVFO_MNG_SN = #{EVFO_MNG_SN}


 /* isry.couns.mngr.consultantabltymng.mapper.DscsnAbilitMngMapper.UpdateExclncCaseRow - 개발지원팀 이태호  */
 UPDATE AYC290 /* 우수사례 */
     SET DEL_YN               = 'Y'              
       , LAST_MDFR_ID         = #{LAST_MDFR_ID}
       , LAST_MDFCN_DT        = SYSDATE
WHERE EXCLNC_CASE_SN = #{EXCLNC_CASE_SN}
  AND CNSLTNT_ID     = #{CNSLTNT_ID}
  AND RLVT_YR        = #{RLVT_YR}
  AND DEL_YN         = 'N'


/* isry.couns.mngr.consultantabltymng.mapper.DscsnAbilitMngMapper.UpdateSuperVisionAll - 응용2팀 정원제  */
UPDATE AYC295 
SET    DEL_YN               =      'Y'              
       , LAST_MDFR_ID       =      #{LAST_MDFR_ID}
       , LAST_MDFCN_DT      =      SYSDATE
WHERE  RLVT_YR                  =       #{RLVT_YR}
AND    TASKWK_TYPE_DEPT_CD      =       #{DEPT_CD}
AND    DEL_YN                   =       'N'


        /* isry.couns.mngr.consultantabltymng.mapper.DscsnAbilitMngMapper.UpdateExclncCaseAll - 응용2팀 정원제  */
        UPDATE AYC290 
	    SET    DEL_YN               =      'Y'              
	           , LAST_MDFR_ID       =      #{LAST_MDFR_ID}
	           , LAST_MDFCN_DT      =      SYSDATE
		WHERE  RLVT_YR                  =       #{RLVT_YR}
		AND    TASKWK_TYPE_DEPT_CD      =       #{DEPT_CD}
		AND    DEL_YN                   =       'N'


 /* isry.couns.mngr.consultantabltymng.mapper.DscsnAbilitMngMapper.UpdateSuperVisionRow - 개발지원팀 이태호  */
 UPDATE AYC295 /* 수퍼비전 */
