/* isry.couns.mngr.consultantabltymng.mapper.DscsnAbilitMngMapper.InsertEvfoAbilitMng - 개발지원팀 이태호 */
SELECT NVL(MAX(CHKLST_MNG_SN)+1 ,1) FROM AYC250
INSERT INTO AYC250 /* 체크리스트관리 */ (CHKLST_MNG_SN , EVFO_MNG_SN , PRVSON_NM , CRT_DT , CRT_ID , MDFCN_DT , MDFR_ID , DEL_YN , FRST_RGTR_ID , FRST_REG_DT , LAST_MDFR_ID , LAST_MDFCN_DT) VALUES (#{MNG_SN} , #{EVFO_MNG_SN} , #{PRVSON_NM} , SYSDATE , #{CRT_ID} , SYSDATE , #{MDFR_ID} , NVL(#{DEL_YN},'N') , #{FRST_RGTR_ID} , SYSDATE , #{LAST_MDFR_ID} , SYSDATE )

mapper.select:
/* isry.couns.mngr.consultantabltymng.mapper.DscsnAbilitMngMapper.selectApraiMngList - 개발지원팀 이태호 */
SELECT T1.RLVT_YR AS RLVT_YR ,(SELECT CMMNS_CD_VALUE_NM FROM SAC100 x WHERE x.CMMNS_CD_ID = 'EVL_TME_SE_CD' AND x.CMMNS_CD_VALUE = T1.EVL_TME_SE_CD) AS EVL_TME_SE_CD --평가회차그룹코드 ,T1.RGTR_ID AS RGTR_ID ,T1.CRT_DT AS CRT_DT ,T1.CFMTN_YN AS CFMTN_YN ,(SELECT CMMNS_CD_VALUE_NM FROM SAC100 x WHERE x.CMMNS_CD_ID = 'EVL_GROUP_SE_CD' AND x.CMMNS_CD_VALUE = T1.EVL_GROUP_SE_CD) AS EVL_GROUP_SE_CD --평가그룹구분코드 ,T1.CHTT_WGHTVA_VALUE AS CHTT_WGHTVA_VALUE ,T1.NTABRD_WGHTVA_VALUE AS NTABRD_WGHTVA_VALUE ,T1.MSNGR_WGHTVA_VALUE AS MSNGR_WGHTVA_VALUE ,T1.PRFMNC_WGHTVA_VALUE AS PRFMNC_WGHTVA_VALUE ,CASE WHEN T1.CHTT_WGHTVA_VALUE IS NOT NULL THEN '채팅상담' WHEN T1.NTABRD_WGHTVA_VALUE IS NOT NULL THEN '게시판상담' WHEN T1.MSNGR_WGHTVA_VALUE IS NOT NULL THEN '메신저상담' WHEN T1.PRFMNC_WGHTVA_VALUE IS NOT NULL THEN '실적상담' END AS EVL_PRVSON ,CASE WHEN T1.CHTT_WGHTVA_VALUE IS NOT NULL THEN T1.CHTT_WGHTVA_VALUE || '%' WHEN T1.NTABRD_WGHTVA_VALUE IS NOT NULL THEN T1.NTABRD_WGHTVA_VALUE || '%' WHEN T1.MSNGR_WGHTVA_VALUE IS NOT NULL THEN T1.MSNGR_WGHTVA_VALUE || '%' WHEN T1.PRFMNC_WGHTVA_VALUE IS NOT NULL THEN T1.PRFMNC_WGHTVA_VALUE || '%' END AS RFLT_RATE ,T1.CHTT_BGNG_YMD AS CHTT_BGNG_YMD ,T1.CHTT_END_YMD AS CHTT_END_YMD ,T1.NTABRD_BGNG_YMD AS NTABRD_BGNG_YMD ,T1.NTABRD_END_YMD AS NTABRD_END_YMD ,T1.MSNGR_BGNG_YMD AS MSNGR_BGNG_YMD ,T1.MSNGR_END_YMD AS MSNGR_END_YMD ,T1.BGNG_YMD AS BGNG_YMD ,T1.END_YMD AS END_YMD ,T1.PRVSON_NM AS PRVSON_NM ,DECODE(T1.BGNG_YMD,NULL,'',SUBSTR(T1.BGNG_YMD,0,4) || '-' || SUBSTR(T1.BGNG_YMD,5,2) || '-' || SUBSTR(T1.BGNG_YMD,7,2) || '~' || SUBSTR(T1.END_YMD,0,4) || '-' || SUBSTR(T1.END_YMD,5,2) || '-' || SUBSTR(T1.END_YMD,7,2)) AS EVL_PRD ,T1.EVFO_MNG_SN AS EVFO_MNG_SN FROM AYC200 T1 /* 평가지관리 */ WHERE 1=1 AND T1.DEL_YN = 'N'
AND T1.RLVT_YR = #{RLVT_YR}
AND T1.EVL_GROUP_SE_CD = #{EVL_GROUP_SE_CD}
AND T1.EVL_TME_SE_CD = #{EVL_TME_SE_CD}


        /* isry.couns.mngr.consultantabltymng.mapper.DscsnAbilitMngMapper.selectEvlTrprMngList - 개발지원팀 이태호  */

        SELECT T1.RLVT_YR                   AS RLVT_YR            
		      ,(SELECT CMMNS_CD_VALUE_NM FROM SAC100 x WHERE x.CMMNS_CD_ID = 'EVL_TME_SE_CD' AND x.CMMNS_CD_VALUE = T1.EVL_TME_SE_CD) AS EVL_TME_SE_CD   --평가회차그룹코드
		      ,(SELECT CMMNS_CD_VALUE_NM FROM SAC100 x WHERE x.CMMNS_CD_ID = 'EVL_GROUP_SE_CD' AND x.CMMNS_CD_VALUE = T1.EVL_GROUP_SE_CD) AS EVL_GROUP_SE_CD   --평가그룹구분코드		      
		      ,T1.EVFO_MNG_SN               AS EVFO_MNG_SN
		FROM AYC200 T1 /* 평가지관리 */    		    
        WHERE 1=1
         AND T1.DEL_YN = 'N'                             



                   AND T1.RLVT_YR = #{RLVT_YR} 




                   AND T1.EVL_GROUP_SE_CD = #{EVL_GROUP_SE_CD} 




                   AND T1.EVL_TME_SE_CD = #{EVL_TME_SE_CD}

/* isry.couns.mngr.consultantabltymng.mapper.DscsnAbilitMngMapper.selectEvlTrprSlctnList - 개발지원팀 이태호 */
SELECT a.USER_ID AS USER_ID ,C##RG.DEC_B64(b.FLNM_ENCPT) AS FLNM_ENCPT ,DECODE((SELECT COUNT(1) FROM AYC240 x WHERE x.EVFO_MNG_SN = #{EVFO_MNG_SN} AND x.DEL_YN = 'N' AND x.CONSTT_ID = a.USER_ID ),1,'true','false') AS CHK FROM SAA200 a /* 사용자 */ ,SCA100 b /* 종사자 */ WHERE 1=1 AND a.ENFSN_NO = b.ENFSN_NO
GROUP BY a.USER_ID, b.FLNM_ENCPT ORDER BY a.USER_ID

mapper.insert:

        /* isry.couns.mngr.consultantabltymng.mapper.DscsnAbilitMngMapper.insertEvlTrprSlctn - 개발지원팀 이태호  */        
        INSERT INTO AYC240
			(EVL_TRPR_SLCTN_SN
			, EVFO_MNG_SN
			, CONSTT_ID
			, DEL_YN
			, FRST_RGTR_ID
			, FRST_REG_DT
			, LAST_MDFR_ID
			, LAST_MDFCN_DT
			)
        VALUES
            (#{EVL_TRPR_SLCTN_SN}
            , #{EVFO_MNG_SN}
            , #{CONSTT_ID}
            , NVL(#{DEL_YN},'N')
            , #{FRST_RGTR_ID}
            , SYSDATE
            , #{LAST_MDFR_ID}
            , SYSDATE 
