        /* isry.couns.mngr.consultantabltymng.mapper.DscsnAbilitMngMapper.UpdateEvlMngList - 개발지원팀 이태호  */
        MERGE INTO
        AYC265 a /* 체크리스트응답 */
		USING   DUAL
		    ON
		    (
		        a.CHKLST_RSPNS_SN   = #{CHKLST_RSPNS_SN}
		    and a.EVL_TRGT_SN       = #{EVL_TRGT_SN}      
		    )
		WHEN MATCHED THEN
		    UPDATE SET
		          a.CHKLST_GROUP_SN = #{CHKLST_GROUP_SN}
		        , a.CHKLST_SCORE    = #{CHKLST_SCORE}
		        , a.CHKLST_QUEST_SN = #{CHKLST_QUEST_SN}
		        , a.MDFCN_DT        = SYSDATE
		        , a.MDFR_ID         = #{LAST_MDFR_ID}
		        , a.DEL_YN          =  NVL(#{DEL_YN} , 'N')
		        , a.LAST_MDFR_ID    = #{LAST_MDFR_ID}
		        , a.LAST_MDFCN_DT   = SYSDATE
		     WHERE 1=1
		     AND   a.EVL_TRGT_SN     = #{EVL_TRGT_SN}
		     AND   a.CHKLST_RSPNS_SN   = #{CHKLST_RSPNS_SN}
		WHEN NOT MATCHED THEN 
		    INSERT
		        (a.CHKLST_RSPNS_SN
		        , a.CHKLST_GROUP_SN
		        , a.EVL_TRGT_SN
		        , a.CHKLST_SCORE
		        , a.CHKLST_QUEST_SN
		        , a.EVL_MNG_SN
		        , a.CRT_DT
		        , a.CRT_ID
		        , a.MDFCN_DT
		        , a.MDFR_ID
		        , a.DEL_YN		        
		        , a.FRST_RGTR_ID
		        , a.FRST_REG_DT
		        , a.LAST_MDFR_ID
		        , a.LAST_MDFCN_DT)
		    VALUES
		        (AYC265_SQ01.NEXTVAL
		        , #{CHKLST_GROUP_SN}
		        , #{EVL_TRGT_SN}
		        , #{CHKLST_SCORE}
		        , #{CHKLST_QUEST_SN}
		        , #{EVL_MNG_SN}
		        , SYSDATE
		        , #{FRST_RGTR_ID}
		        , SYSDATE
		        , #{LAST_MDFR_ID}
		        , NVL(#{DEL_YN} , 'N')		        
		        , #{FRST_RGTR_ID}
		        , SYSDATE
		        , #{LAST_MDFR_ID}
		        , SYSDATE
		        )


