/* isry.couns.mngr.consultantabltymng.mapper.DscsnAbilitMngMapper.selectExclncCaseMngList - 개발지원팀 이태호 */
SELECT a.EXCLNC_CASE_SN AS EXCLNC_CASE_SN ,a.CNSLTNT_ID AS CNSLTNT_ID ,a.RLVT_YR AS RLVT_YR ,a.TASKWK_TYPE_DEPT_CD AS TASKWK_TYPE_DEPT_CD ,a.ATFINO AS ATFINO ,C##RG.DEC_B64(c.FLNM_ENCPT) AS CONSTT_NM ,(SELECT COUNT(1) FROM SAB821 e WHERE e.ATFINO = a.ATFINO AND e.ATCMFL_CL_NM = '1월' AND e.FILE_STTS_SE_CD = 'N') AS ATFINO1 ,(SELECT COUNT(1) FROM SAB821 e WHERE e.ATFINO = a.ATFINO AND e.ATCMFL_CL_NM = '2월' AND e.FILE_STTS_SE_CD = 'N') AS ATFINO2 ,(SELECT COUNT(1) FROM SAB821 e WHERE e.ATFINO = a.ATFINO AND e.ATCMFL_CL_NM = '3월' AND e.FILE_STTS_SE_CD = 'N') AS ATFINO3 ,(SELECT COUNT(1) FROM SAB821 e WHERE e.ATFINO = a.ATFINO AND e.ATCMFL_CL_NM = '4월' AND e.FILE_STTS_SE_CD = 'N') AS ATFINO4 ,(SELECT COUNT(1) FROM SAB821 e WHERE e.ATFINO = a.ATFINO AND e.ATCMFL_CL_NM = '5월' AND e.FILE_STTS_SE_CD = 'N') AS ATFINO5 ,(SELECT COUNT(1) FROM SAB821 e WHERE e.ATFINO = a.ATFINO AND e.ATCMFL_CL_NM = '6월' AND e.FILE_STTS_SE_CD = 'N') AS ATFINO6 ,(SELECT COUNT(1) FROM SAB821 e WHERE e.ATFINO = a.ATFINO AND e.ATCMFL_CL_NM = '7월' AND e.FILE_STTS_SE_CD = 'N') AS ATFINO7 ,(SELECT COUNT(1) FROM SAB821 e WHERE e.ATFINO = a.ATFINO AND e.ATCMFL_CL_NM = '8월' AND e.FILE_STTS_SE_CD = 'N') AS ATFINO8 ,(SELECT COUNT(1) FROM SAB821 e WHERE e.ATFINO = a.ATFINO AND e.ATCMFL_CL_NM = '9월' AND e.FILE_STTS_SE_CD = 'N') AS ATFINO9 ,(SELECT COUNT(1) FROM SAB821 e WHERE e.ATFINO = a.ATFINO AND e.ATCMFL_CL_NM = '10월' AND e.FILE_STTS_SE_CD = 'N') AS ATFINO10 ,(SELECT COUNT(1) FROM SAB821 e WHERE e.ATFINO = a.ATFINO AND e.ATCMFL_CL_NM = '11월' AND e.FILE_STTS_SE_CD = 'N') AS ATFINO11 ,(SELECT COUNT(1) FROM SAB821 e WHERE e.ATFINO = a.ATFINO AND e.ATCMFL_CL_NM = '12월' AND e.FILE_STTS_SE_CD = 'N') AS ATFINO12 FROM AYC290 a /* 우수사례 */ ,SAA200 b /* 사용자테이블 */ ,SCA100 c /* 개인종사자 */ WHERE 1=1 AND a.CNSLTNT_ID = b.USER_ID AND b.ENFSN_NO = c.ENFSN_NO AND a.DEL_YN = 'N' AND c.DEL_YN = 'N'
AND a.RLVT_YR = #{RLVT_YR}
AND c.OGDP_DEPT_CD = #{DEPT_CD}
AND a.CNSLTNT_ID = #{loginId}

/* isry.couns.mngr.consultantabltymng.mapper.DscsnAbilitMngMapper.selectSuperVisionMngList - 개발지원팀 이태호 */
SELECT a.SUPERV_CASE_SN AS SUPERV_CASE_SN ,a.CNSLTNT_ID AS CNSLTNT_ID ,a.REG_DT AS REG_DT ,a.RLVT_YR AS RLVT_YR ,a.TASKWK_TYPE_DEPT_CD AS TASKWK_TYPE_DEPT_CD ,a.ATFINO AS ATFINO ,C##RG.DEC_B64(c.FLNM_ENCPT) AS CONSTT_NM ,(SELECT COUNT(1) FROM SAB821 e WHERE e.ATFINO = a.ATFINO AND e.ATCMFL_CL_NM = '1차' AND e.FILE_STTS_SE_CD = 'N') AS ATFINO1 ,(SELECT COUNT(1) FROM SAB821 e WHERE e.ATFINO = a.ATFINO AND e.ATCMFL_CL_NM = '2차' AND e.FILE_STTS_SE_CD = 'N') AS ATFINO2 ,(SELECT COUNT(1) FROM SAB821 e WHERE e.ATFINO = a.ATFINO AND e.ATCMFL_CL_NM = '3차' AND e.FILE_STTS_SE_CD = 'N') AS ATFINO3 ,(SELECT COUNT(1) FROM SAB821 e WHERE e.ATFINO = a.ATFINO AND e.ATCMFL_CL_NM = '4차' AND e.FILE_STTS_SE_CD = 'N') AS ATFINO4 ,(SELECT COUNT(1) FROM SAB821 e WHERE e.ATFINO = a.ATFINO AND e.ATCMFL_CL_NM = '5차' AND e.FILE_STTS_SE_CD = 'N') AS ATFINO5 ,(SELECT COUNT(1) FROM SAB821 e WHERE e.ATFINO = a.ATFINO AND e.ATCMFL_CL_NM = '6차' AND e.FILE_STTS_SE_CD = 'N') AS ATFINO6 FROM AYC295 a /* 수퍼비전 */ ,SAA200 b /* 사용자테이블 */ ,SCA100 c /* 개인종사자 */ WHERE 1=1 AND a.CNSLTNT_ID = b.USER_ID AND b.ENFSN_NO = c.ENFSN_NO AND a.DEL_YN = 'N' AND c.DEL_YN = 'N'
AND a.RLVT_YR = #{RLVT_YR}
AND c.OGDP_DEPT_CD = #{DEPT_CD}
AND a.CNSLTNT_ID = #{loginId}

/* isry.couns.mngr.consultantabltymng.mapper.DscsnAbilitMngMapper.selectExclncCaseConsttList - 개발지원팀 이태호 */ SELECT a.USER_ID AS CONSTT_ID , C##RG.DEC_B64(b.FLNM_ENCPT) AS CONSTT_NM , b.OGDP_DEPT_CD AS DEPT_CD FROM SAA200 a /* 사용자테이블 */ ,SCA100 b /* 개인종사자 */ WHERE 1=1 AND a.USER_CNTN_INTRCP_YN = 'N' /* 사용자접속차단여부 */ AND a.JOIN_APRV_YN = 'Y' /* 가입승인여부 */ AND b.DEL_YN = 'N' /* 삭제 여부 */ AND a.ENFSN_NO = b.ENFSN_NO
AND b.OGDP_DEPT_CD = #{DEPT_CD}
AND NOT EXISTS (SELECT * FROM AYC290 x /* 우수사례 */ WHERE x.CNSLTNT_ID = a.USER_ID AND x.RLVT_YR = #{RLVT_YR} AND x.DEL_YN = 'N' ) ORDER BY USER_ID ASC

/* isry.couns.mngr.consultantabltymng.mapper.DscsnAbilitMngMapper.selectSuperVisionConsttList - 개발지원팀 이태호 */
SELECT a.USER_ID AS CONSTT_ID ,C##RG.DEC_B64(b.FLNM_ENCPT) AS CONSTT_NM ,b.OGDP_DEPT_CD AS DEPT_CD FROM SAA200 a /* 사용자테이블 */ ,SCA100 b /* 개인종사자 */ WHERE 1=1 AND a.USER_CNTN_INTRCP_YN = 'N' /* 사용자접속차단여부 */ AND a.JOIN_APRV_YN = 'Y' /* 가입승인여부 */ AND b.DEL_YN = 'N' /* 삭제 여부 */ AND a.ENFSN_NO = b.ENFSN_NO
AND b.OGDP_DEPT_CD = #{DEPT_CD}
AND NOT EXISTS (SELECT * FROM AYC295 x /* 수퍼비전 */ WHERE x.CNSLTNT_ID = a.USER_ID AND x.RLVT_YR = #{RLVT_YR} AND x.DEL_YN = 'N') ORDER BY USER_ID ASC

