/* isry.couns.mngr.consultantabltymng.mapper.DscsnAbilitMngMapper.selectEduHstrList - 응용2팀 정원제 */ SELECT T2.EDU_ATDRN_SN AS EDU_ATDRN_SN , T1.EDU_ESTBL_SN AS EDU_ESTBL_SN , T1.EDU_YMD AS EDU_YMD , T1.EDU_TTL_NM AS EDU_TTL_NM , T3.OGDP_INST_NO AS OGDP_INST_NO , C##RG.DEC_B64(T3.FLNM_ENCPT) AS FLNM_ENCPT , trunc((T1.EDU_COMPL_HR / 60), 1) AS EDU_COMPL_HR , T2.EDU_ATND_YN AS EDU_ATND_YN , T2.CTCPL_OTPT_NO AS CTCPL_OTPT_NO FROM AYC190 T1 /* 교육관리 */ , AYC195 T2 /* 교육 참석자 관리 */ , SCA100 T3 /* 종사자 */ , SAA200 T4 /* 사용자 */ WHERE 1=1 AND T1.EDU_ESTBL_SN = T2.EDU_ESTBL_SN AND T2.CNSLTNT_ID = T4.USER_ID AND T4.ENFSN_NO = T3.ENFSN_NO AND T1.DEL_YN = 'N' AND T2.DEL_YN = 'N' AND T1.EDU_YMD LIKE #{YYYY}||'%'
AND T2.EDU_ATND_YN = #{COMPL_YN}
AND T2.CNSLTNT_ID = #{loginId}
ORDER BY T1.EDU_ESTBL_SN DESC , T2.CNSLTNT_ID DESC

