/* isry.couns.mngr.consultantabltymng.mapper.DscsnAbilitMngMapper.selectEduMngList - 개발지원팀 이태호 */
SELECT a.EDU_ESTBL_SN AS EDU_ESTBL_SN ,a.EDU_TTL_NM AS EDU_TTL_NM ,a.EDU_YMD AS EDU_YMD ,a.EDU_BGNG_HR AS EDU_BGNG_HR ,a.EDU_END_HR AS EDU_END_HR ,trunc((a.EDU_COMPL_HR / 60),1) AS EDU_COMPL_HR ,(SELECT CMMNS_CD_VALUE_NM FROM SAC100 x WHERE x.CMMNS_CD_ID = 'EDU_TYPE_SE_CD' AND x.CMMNS_CD_VALUE = a.EDU_TYPE_SE_CD) AS EDU_TYPE_SE_CD --교육유형구분코드 ,a.EDU_INSTR_NM AS EDU_INSTR_NM ,nvl(a.CYBER_EDU_NOPE, 0) AS CYBER_EDU_NOPE ,nvl(a.TLPHON_EDU_NOPE, 0) AS TLPHON_EDU_NOPE ,nvl(a.MBLA_EDU_NOPE, 0) AS MBLA_EDU_NOPE ,substr(a.EDU_YMD, 0, 4) || '.' || substr(a.EDU_YMD, 5, 2) || '.' || substr(a.EDU_YMD, 7, 2) || '(' || substr(a.EDU_BGNG_HR, 0, 2) || ':' || substr(a.EDU_BGNG_HR, 3, 2) || '~' || substr(a.EDU_END_HR, 0, 2) || ':' || substr(a.EDU_END_HR, 3, 2) || ')' AS EDU_DT FROM AYC190 a /* 교육 관리 */ WHERE 1=1
AND a.EDU_TYPE_SE_CD = #{EDU_TYPE_SE_CD}
AND SUBSTR(a.EDU_YMD,1,4) = #{EDU_YMD}
AND a.DEL_YN = 'N' ORDER BY a.EDU_YMD DESC, a.EDU_BGNG_HR DESC, a.EDU_END_HR DESC

