/* isry.couns.mngr.consultantabltymng.mapper.DscsnAbilitMngMapper.UpdateEduMng - 개발지원팀 이태호  */

    SELECT AYC190_SQ01.CURRVAL AS ESTBL_SN 
    FROM   DUAL           

MERGE INTO
AYC190 a /* 교육 관리 */      
USING   DUAL
    ON
    (
        a.EDU_ESTBL_SN   = #{EDU_ESTBL_SN}  
    )
WHEN MATCHED THEN
    UPDATE SET        
          a.EDU_TTL_NM      = #{EDU_TTL_NM}
        , a.EDU_THMA_NM     = #{EDU_THMA_NM}
        , a.EDU_YMD         = #{EDU_YMD}
        , a.EDU_BGNG_HR     = #{EDU_BGNG_HR}
        , a.EDU_END_HR      = #{EDU_END_HR}
        , a.EDU_COMPL_HR    = #{EDU_COMPL_HR}
        , a.EDU_TYPE_SE_CD  = #{EDU_TYPE_SE_CD}
        , a.EDU_INSTR_NM    = #{EDU_INSTR_NM}
        , a.ATFINO          = #{ATFINO}
        , a.CYBER_EDU_NOPE  = #{CYBER_EDU_NOPE}
        , a.TLPHON_EDU_NOPE = #{TLPHON_EDU_NOPE}
        , a.MBLA_EDU_NOPE   = #{MBLA_EDU_NOPE}
        , a.FRST_RGTR_ID    = #{FRST_RGTR_ID}
        , a.FRST_REG_DT     = SYSDATE
        , a.LAST_MDFR_ID    = #{LAST_MDFR_ID}
        , a.LAST_MDFCN_DT   = SYSDATE
    WHERE a.EDU_ESTBL_SN   = #{EDU_ESTBL_SN}    
WHEN NOT MATCHED THEN 
    INSERT
        (a.EDU_ESTBL_SN
        , a.EDU_TTL_NM
        , a.EDU_THMA_NM
        , a.EDU_YMD
        , a.EDU_BGNG_HR
        , a.EDU_END_HR
        , a.EDU_COMPL_HR
        , a.EDU_TYPE_SE_CD
        , a.EDU_INSTR_NM
        , a.ATFINO
        , a.CYBER_EDU_NOPE
        , a.TLPHON_EDU_NOPE
        , a.MBLA_EDU_NOPE
        , a.FRST_RGTR_ID
        , a.FRST_REG_DT
        , a.LAST_MDFR_ID
        , a.LAST_MDFCN_DT)
    VALUES
        (AYC190_SQ01.NEXTVAL
        , #{EDU_TTL_NM}
        , #{EDU_THMA_NM}
        , #{EDU_YMD}
        , #{EDU_BGNG_HR}
        , #{EDU_END_HR}
        , #{EDU_COMPL_HR}
        , #{EDU_TYPE_SE_CD}
        , #{EDU_INSTR_NM}
        , #{ATFINO}
        , #{CYBER_EDU_NOPE}
        , #{TLPHON_EDU_NOPE}
        , #{MBLA_EDU_NOPE}
        , #{FRST_RGTR_ID}
        , SYSDATE
        , #{LAST_MDFR_ID}
        , SYSDATE
        )


/* isry.couns.mngr.consultantabltymng.mapper.DscsnAbilitMngMapper.UpdateEduMngSaveList - 개발지원팀 이태호  */
MERGE INTO
