          a.OGDP_DEPT_CD    = #{OGDP_DEPT_CD}
        , a.CNSLTNT_ID      = #{CNSLTNT_ID}
        , a.EDU_ATND_YN     = #{EDU_ATND_YN}
        , a.ATFINO          = #{ATFINO}
        , a.CTCPL_OTPT_NO   = #{CTCPL_OTPT_NO}              
        , a.LAST_MDFR_ID    = #{LAST_MDFR_ID}
        , a.LAST_MDFCN_DT   = SYSDATE
     WHERE 1=1
       AND a.EDU_ATDRN_SN   = #{EDU_ATDRN_SN} 
       AND a.EDU_ESTBL_SN   = #{EDU_ESTBL_SN}   
WHEN NOT MATCHED THEN 
