        , a.OGDP_DEPT_CD
        , a.CNSLTNT_ID
        , a.EDU_ATND_YN
        , a.FRST_RGTR_ID
        , a.FRST_REG_DT
        , a.LAST_MDFR_ID
        , a.LAST_MDFCN_DT
        )
    VALUES
        (AYC195_SQ01.NEXTVAL
        , #{EDU_ESTBL_SN}
        , #{OGDP_DEPT_CD}
        , #{CNSLTNT_ID}
        , #{EDU_ATND_YN}                
        , #{FRST_RGTR_ID}
        , SYSDATE
        , #{LAST_MDFR_ID}
        , SYSDATE
